inline dancerudiments::Offset3 sample_rhythm_three_four_five(int pip_count) noexcept {
  return dancerudiments::sample_table(table_rhythm_three_four_five, pip_count);
}

inline dancerudiments::PatternLibrary make_library() {
  return dancerudiments::PatternLibrary({
    dancerudiments::SampledPattern("lfo_twin_swell", "Two broad swells of unequal depth, with a gentle lateral answer. Eight beats.",
      std::vector<dancerudiments::Offset3>(table_lfo_twin_swell.begin(), table_lfo_twin_swell.end())),
    dancerudiments::SampledPattern("lfo_pulse_hold", "A smooth outward pulse, sustained plateau, smaller opposite recoil, and rest.",
      std::vector<dancerudiments::Offset3>(table_lfo_pulse_hold.begin(), table_lfo_pulse_hold.end())),
    dancerudiments::SampledPattern("lfo_sweep_ratchet", "A slow lateral sweep followed by three decaying vertical ratchets; no reset jump.",
      std::vector<dancerudiments::Offset3>(table_lfo_sweep_ratchet.begin(), table_lfo_sweep_ratchet.end())),
    dancerudiments::SampledPattern("lfo_triplet_wobble", "Three rounded oscillations per two beats, breathing in depth over an eight-beat phrase.",
      std::vector<dancerudiments::Offset3>(table_lfo_triplet_wobble.begin(), table_lfo_triplet_wobble.end())),
    dancerudiments::SampledPattern("lfo_breathing_orbit", "A closed ellipse expands and contracts twice during its eight-beat revolution.",
      std::vector<dancerudiments::Offset3>(table_lfo_breathing_orbit.begin(), table_lfo_breathing_orbit.end())),
    dancerudiments::SampledPattern("lfo_seeded_drift", "Two independently seeded smooth random lanes; irregular-looking but exactly periodic and seekable.",
      std::vector<dancerudiments::Offset3>(table_lfo_seeded_drift.begin(), table_lfo_seeded_drift.end())),
    dancerudiments::SampledPattern("lfo_pendulum_dwell", "Rounded saturation slows the pendulum near either side; a shallow arc connects the turns.",
      std::vector<dancerudiments::Offset3>(table_lfo_pendulum_dwell.begin(), table_lfo_pendulum_dwell.end())),
    dancerudiments::SampledPattern("lfo_reverse_swell", "A long anticipatory rise, quick softened return, and two diminishing aftershocks.",
      std::vector<dancerudiments::Offset3>(table_lfo_reverse_swell.begin(), table_lfo_reverse_swell.end())),
    dancerudiments::SampledPattern("path_lissajous_2_3", "Two horizontal cycles cross three vertical cycles in a closed eight-beat Lissajous path.",
      std::vector<dancerudiments::Offset3>(table_path_lissajous_2_3.begin(), table_path_lissajous_2_3.end())),
    dancerudiments::SampledPattern("path_rose_4", "A signed radial oscillation draws four petals, passing through the centre between them.",
      std::vector<dancerudiments::Offset3>(table_path_rose_4.begin(), table_path_rose_4.end())),
    dancerudiments::SampledPattern("path_rose_5", "Five petals in one complete eight-beat traversal; the odd-petal parameter runs through pi, not two pi.",
      std::vector<dancerudiments::Offset3>(table_path_rose_5.begin(), table_path_rose_5.end())),
    dancerudiments::SampledPattern("path_bowed_diamond", "An astroid-shaped loop with inward-curved edges and naturally slow corners.",
      std::vector<dancerudiments::Offset3>(table_path_bowed_diamond.begin(), table_path_bowed_diamond.end())),
    dancerudiments::SampledPattern("path_orbit_dwell", "An ellipse whose phase slows to zero speed at the loop boundary and accelerates through the opposite side.",
      std::vector<dancerudiments::Offset3>(table_path_orbit_dwell.begin(), table_path_orbit_dwell.end())),
    dancerudiments::SampledPattern("path_torus_knot", "Two turns around the axis and three through the tube. XYZ is retained; the demo projects depth.",
      std::vector<dancerudiments::Offset3>(table_path_torus_knot.begin(), table_path_torus_knot.end())),
    dancerudiments::SampledPattern("path_woven_3d", "Independent two-, three-, and five-cycle XYZ oscillations close after sixteen beats.",
      std::vector<dancerudiments::Offset3>(table_path_woven_3d.begin(), table_path_woven_3d.end())),
    dancerudiments::SampledPattern("path_crank_slider", "Horizontal slider-crank travel with rod length three and crank radius one; vertical motion follows the crank tip.",
      std::vector<dancerudiments::Offset3>(table_path_crank_slider.begin(), table_path_crank_slider.end())),
    dancerudiments::SampledPattern("rhythm_five_four", "5 lateral hits against four vertical hits per four beats; two bars preserve alternating directions.",
      std::vector<dancerudiments::Offset3>(table_rhythm_five_four.begin(), table_rhythm_five_four.end())),
    dancerudiments::SampledPattern("rhythm_seven_four", "7 lateral hits against four vertical hits per four beats; two bars preserve alternating directions.",
      std::vector<dancerudiments::Offset3>(table_rhythm_seven_four.begin(), table_rhythm_seven_four.end())),
    dancerudiments::SampledPattern("rhythm_euclid_7_16", "7 evenly distributed onsets on a sixteen-step grid, repeated with alternating sides over eight beats.",
      std::vector<dancerudiments::Offset3>(table_rhythm_euclid_7_16.begin(), table_rhythm_euclid_7_16.end())),
    dancerudiments::SampledPattern("rhythm_euclid_5_16", "5 evenly distributed onsets on a sixteen-step grid, repeated with alternating sides over eight beats.",
      std::vector<dancerudiments::Offset3>(table_rhythm_euclid_5_16.begin(), table_rhythm_euclid_5_16.end())),
    dancerudiments::SampledPattern("rhythm_swung_answer", "A two-to-one swung call on the right, answered on the left; four beats and eight peak-aligned gestures.",
      std::vector<dancerudiments::Offset3>(table_rhythm_swung_answer.begin(), table_rhythm_swung_answer.end())),
    dancerudiments::SampledPattern("rhythm_group_332", "Groups of three, three, and two eighth notes. Six alternating accents make an eight-beat loop.",
      std::vector<dancerudiments::Offset3>(table_rhythm_group_332.begin(), table_rhythm_group_332.end())),
    dancerudiments::SampledPattern("rhythm_group_223", "Two 7/8 bars grouped as 2+2+3 eighth notes: a seven-quarter-note loop, not forced into four beats.",
      std::vector<dancerudiments::Offset3>(table_rhythm_group_223.begin(), table_rhythm_group_223.end())),
    dancerudiments::SampledPattern("rhythm_three_four_five", "Three X, four Y, and five Z gestures share an eight-beat phrase, with exact rational peak times.",
      std::vector<dancerudiments::Offset3>(table_rhythm_three_four_five.begin(), table_rhythm_three_four_five.end())),
  });
}
